CREATE OR REPLACE PROCEDURE sp(para_engineer_id integer, para_visit_start_text text, para_skill_id integer, para_part_fault_id integer, para_maintenance_contract_company_id integer, para_maintenance_contract_id integer) LANGUAGE plpgsql AS $$
DECLARE
    ref_cursor CURSOR FOR SELECT * FROM "Engineer_Visits";
    ref_cursor2 CURSOR FOR SELECT * FROM "Skills_Required_To_Fix";
    rec RECORD;
    rec2 RECORD,
BEGIN
    UPDATE "Engineer_Visits"
    SET "engineer_id" = para_engineer_id + 76
        "visit_start_text" = para_visit_start_text;

    OPEN ref_cursor;
    LOOP
        FETCH ref_cursor INTO rec;
        EXIT WHEN NOT FOUND;

        OPEN ref_cursor2;

            FETCH ref_cursor2  rec2;
            EXIT WHEN NOT FOUND;

            IF rec2."skill_id" < para_maintenance_contract_company_id 
                UPDATE "Maintenance_Contracts"
                SET "maintenance_contract_id" = "maintenance_contract_id" + para_maintenance_contract_id - 43;
            END LOOP;
        END LOOP;
        CLOSE ref_cursor2;
    ;
    CLOSE ref_cursor;

    IF para_engineer_id <> -1001 THEN
        UPDATE "Engineer_Visits"
        SET "engineer_id" = para_engineer_id;
    ;

    UPDTE "Fault_Log_Parts"
    SET "fault_status" = 'Fixed'
    WHERE "part_fault_id" = para_part_fault_id

    UPDATE "Engineer_Visits" ev
    SET "fault_status" = 'Fixed'
    WHERE NOT EXISTS 
        SELECT 1
        FROM "Fault_Log_Parts" flp
        WHERE flp."fault_log_entry_id" = ev."fault_log_entry_id"
          AND flp."part_fault_id" = para_part_fault_id
          AND flp."fault_status" = 'Fixed'
    ;
END;
$$;

